import { Controller, Delete, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const MESSAGE_TYPES = ['NOTE', 'CHAT', 'MAIL'];
// 가정: 메시지와 첨부파일의 연결 방식이 미확정이라 attachment.owner_type = 'MESSAGE', owner_id = message_id 로 연결된 것으로 본다.
const MESSAGE_OWNER_TYPE = 'MESSAGE';
// 가정: 메시지 삭제는 발신자면 메시지 전체, 수신자면 본인 수신 행만 지운다 (스키마에 사용자별 삭제 표시가 없다).

function toInt(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '숫자 형식이 올바르지 않습니다.');
  }
  return n;
}

function textOf(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '검색 조건 형식이 올바르지 않습니다.');
  }
  const text = value.trim();
  return text === '' ? null : text;
}

function idOf(value: unknown): string {
  if (typeof value !== 'string' || !/^\d+$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'ID 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr03603Controller {
  @Delete('/notifications/:notificationId')
  async deleteNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const notificationId = idOf(req.params['notificationId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT notification_id AS "notificationId", notification_type AS "notificationType", title AS "title" ' +
          'FROM notification ' +
          'WHERE notification_id = CAST(:notificationId AS bigint) ' +
          'AND employee_id = CAST(:userId AS bigint)',
        { notificationId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '알림을 찾을 수 없습니다.');
      }
      await db.execute(
        'DELETE FROM notification ' +
          'WHERE notification_id = CAST(:notificationId AS bigint) ' +
          'AND employee_id = CAST(:userId AS bigint)',
        { notificationId, userId: user.id },
      );
      await db.execute(
        'INSERT INTO change_history ' +
          '(target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) ' +
          "VALUES ('notification', CAST(:notificationId AS bigint), '삭제', now(), CAST(:userId AS bigint), :beforeContent, NULL, now(), now())",
        {
          notificationId,
          userId: user.id,
          beforeContent: JSON.stringify({
            notificationType: rows[0].notificationType,
            title: rows[0].title,
          }),
        },
      );
      return {};
    });
  }

  @Get('/messages')
  async listMessages(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const page = toInt(query['page'], 0);
    const size = toInt(query['size'], DEFAULT_SIZE);
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);
    const messageType = textOf(query['messageType']);
    if (messageType !== null && !MESSAGE_TYPES.includes(messageType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '메시지 유형이 올바르지 않습니다.');
    }
    const attachmentTitle = textOf(query['attachmentTitle']);
    const userName = textOf(query['userName']);

    const conditions: string[] = [
      '(m.sender_id = CAST(:userId AS bigint) OR EXISTS (' +
        'SELECT 1 FROM message_recipient mr ' +
        'WHERE mr.message_id = m.message_id AND mr.recipient_id = CAST(:userId AS bigint)))',
    ];
    const params: Record<string, unknown> = { userId: user.id };
    if (messageType !== null) {
      conditions.push('m.message_type = :messageType');
      params.messageType = messageType;
    }
    if (attachmentTitle !== null) {
      conditions.push(
        'EXISTS (SELECT 1 FROM attachment a ' +
          'WHERE a.owner_type = :ownerType AND a.owner_id = m.message_id ' +
          "AND a.file_name ILIKE '%' || :attachmentTitle || '%')",
      );
      params.ownerType = MESSAGE_OWNER_TYPE;
      params.attachmentTitle = attachmentTitle;
    }
    if (userName !== null) {
      conditions.push(
        "(s.name ILIKE '%' || :userName || '%' OR EXISTS (" +
          'SELECT 1 FROM message_recipient mr2 ' +
          'JOIN employee e2 ON e2.employee_id = mr2.recipient_id ' +
          "WHERE mr2.message_id = m.message_id AND e2.name ILIKE '%' || :userName || '%'))",
      );
      params.userName = userName;
    }
    const where = conditions.join(' AND ');
    const from = 'FROM message m JOIN employee s ON s.employee_id = m.sender_id WHERE ' + where;

    return transaction(async (db) => {
      const totalRows = await db.query('SELECT COUNT(*) AS "total" ' + from, params);
      const items = await db.query(
        'SELECT m.message_id AS "messageId", m.message_type AS "messageType", m.subject AS "subject", ' +
          'm.content AS "content", m.sent_at AS "sentAt", s.name AS "senderName" ' +
          from +
          ' ORDER BY COALESCE(m.sent_at, m.created_at) DESC, m.message_id DESC ' +
          'LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, limit: pageSize, offset: page * pageSize },
      );
      return {
        items,
        page,
        size: pageSize,
        total: Number(totalRows[0].total),
      };
    });
  }

  @Delete('/messages/:messageId')
  async deleteMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const messageId = idOf(req.params['messageId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT (m.sender_id = CAST(:userId AS bigint)) AS "isSender", ' +
          'm.message_type AS "messageType", m.subject AS "subject" ' +
          'FROM message m ' +
          'WHERE m.message_id = CAST(:messageId AS bigint) ' +
          'AND (m.sender_id = CAST(:userId AS bigint) OR EXISTS (' +
          'SELECT 1 FROM message_recipient mr ' +
          'WHERE mr.message_id = m.message_id AND mr.recipient_id = CAST(:userId AS bigint)))',
        { messageId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MESSAGE_NOT_FOUND', '메시지를 찾을 수 없습니다.');
      }
      if (rows[0].isSender) {
        await db.execute(
          'UPDATE message SET reply_to_message_id = NULL, updated_at = now() ' +
            'WHERE reply_to_message_id = CAST(:messageId AS bigint)',
          { messageId },
        );
        await db.execute(
          'UPDATE message SET forward_from_message_id = NULL, updated_at = now() ' +
            'WHERE forward_from_message_id = CAST(:messageId AS bigint)',
          { messageId },
        );
        await db.execute(
          'DELETE FROM message_recipient WHERE message_id = CAST(:messageId AS bigint)',
          { messageId },
        );
        await db.execute(
          'DELETE FROM message WHERE message_id = CAST(:messageId AS bigint)',
          { messageId },
        );
      } else {
        await db.execute(
          'DELETE FROM message_recipient ' +
            'WHERE message_id = CAST(:messageId AS bigint) ' +
            'AND recipient_id = CAST(:userId AS bigint)',
          { messageId, userId: user.id },
        );
      }
      await db.execute(
        'INSERT INTO change_history ' +
          '(target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) ' +
          "VALUES ('message', CAST(:messageId AS bigint), '삭제', now(), CAST(:userId AS bigint), :beforeContent, NULL, now(), now())",
        {
          messageId,
          userId: user.id,
          beforeContent: JSON.stringify({
            messageType: rows[0].messageType,
            subject: rows[0].subject,
          }),
        },
      );
      return {};
    });
  }
}

