import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  Pager,
  Pairs,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const NOTIFICATION_TYPES: [string, string][] = [
  ['ALERT', '알림'],
  ['MENTION', '멘션'],
];

const MESSAGE_TYPES: [string, string][] = [
  ['NOTE', '쪽지'],
  ['CHAT', '대화'],
  ['MAIL', '메일'],
];

const SIZE = 20;

type Target = { kind: 'notification' | 'message'; row: Row } | null;

export default function FnSfr03603Page({ role, notify }: PageProps) {
  const [notiType, setNotiType] = useState('');
  const [notiApplied, setNotiApplied] = useState('');
  const [notiPage, setNotiPage] = useState(0);

  const [msgType, setMsgType] = useState('');
  const [attachmentTitle, setAttachmentTitle] = useState('');
  const [userName, setUserName] = useState('');
  const [msgApplied, setMsgApplied] = useState<Row>({});
  const [msgPage, setMsgPage] = useState(0);

  const [target, setTarget] = useState<Target>(null);
  const [detail, setDetail] = useState<Row | null>(null);

  const notis = useData<Page>(
    () => call<Page>('GET', '/notifications', role, undefined, {
      notificationType: notiApplied,
      page: notiPage,
      size: SIZE,
    }),
    [notiApplied, notiPage],
  );
  const msgs = useData<Page>(
    () => call<Page>('GET', '/messages', role, undefined, {
      ...msgApplied,
      page: msgPage,
      size: SIZE,
    }),
    [msgApplied, msgPage],
  );

  const notiItems = notis.data?.items ?? [];
  const msgItems = msgs.data?.items ?? [];
  const unread = notiItems.filter((r) => r.readYn !== true).length;

  async function markRead(row: Row) {
    try {
      await call('POST', '/notifications/' + String(row.notificationId) + '/read', role, {});
      notify('알림을 확인 처리했습니다.');
      notis.reload();
    } catch (e) {
      notify(e instanceof Error ? e.message : '처리하지 못했습니다.');
    }
  }

  async function remove() {
    if (!target) {
      return;
    }
    if (target.kind === 'notification') {
      await call('DELETE', '/notifications/' + String(target.row.notificationId), role);
      notify('알림을 삭제했습니다.');
      notis.reload();
    } else {
      await call('DELETE', '/messages/' + String(target.row.messageId), role);
      notify('메시지를 삭제했습니다.');
      msgs.reload();
    }
    setTarget(null);
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>알림</h2>
        <p className="big">{notis.data?.total ?? 0}</p>
      </section>
      <section className="box span-4">
        <h2>안 읽은 알림</h2>
        <p className="big">{unread}</p>
      </section>
      <section className="box span-4">
        <h2>메시지</h2>
        <p className="big">{msgs.data?.total ?? 0}</p>
      </section>

      <section className="box span-12">
        <h2>알림 이력</h2>
        <Filters
          onSearch={() => {
            setNotiPage(0);
            setNotiApplied(notiType);
          }}
          onReset={() => {
            setNotiType('');
            setNotiPage(0);
            setNotiApplied('');
          }}
        >
          <Field label="알림 구분">
            <Select value={notiType} onChange={setNotiType} options={NOTIFICATION_TYPES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={notis.data?.total} />
        {notis.error ? <ErrorText text={notis.error} /> : null}
        <DataTable
          rows={notiItems}
          empty="검색 결과가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'notificationType', label: '알림 구분', render: (r) => <Badge value={r.notificationType === 'MENTION' ? '멘션' : '알림'} /> },
            { key: 'title', label: '제목' },
            { key: 'summary', label: '요약' },
            { key: 'readYn', label: '읽음 여부', render: (r) => <Badge value={r.readYn === true ? '읽음' : '대기'} /> },
            { key: 'occurredAt', label: '이벤트 발생 일시', render: (r) => <DateText value={r.occurredAt} time /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span onClick={(e) => e.stopPropagation()}>
                  {r.readYn !== true ? (
                    <button type="button" onClick={() => markRead(r)}>확인</button>
                  ) : null}
                  <button type="button" onClick={() => setTarget({ kind: 'notification', row: r })}>삭제</button>
                </span>
              ),
            },
          ]}
        />
        <Pager page={notiPage} size={SIZE} total={notis.data?.total ?? 0} onPage={setNotiPage} />
      </section>

      <section className="box span-12">
        <h2>통합 메시지</h2>
        <Filters
          onSearch={() => {
            setMsgPage(0);
            setMsgApplied({ messageType: msgType, attachmentTitle, userName });
          }}
          onReset={() => {
            setMsgType('');
            setAttachmentTitle('');
            setUserName('');
            setMsgPage(0);
            setMsgApplied({});
          }}
        >
          <Field label="메시지 유형">
            <Select value={msgType} onChange={setMsgType} options={MESSAGE_TYPES} placeholder="전체" />
          </Field>
          <Field label="파일명">
            <TextInput value={attachmentTitle} onChange={setAttachmentTitle} />
          </Field>
          <Field label="성명">
            <TextInput value={userName} onChange={setUserName} />
          </Field>
        </Filters>
        <Band total={msgs.data?.total} />
        {msgs.error ? <ErrorText text={msgs.error} /> : null}
        <DataTable
          rows={msgItems}
          empty="검색 결과가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'messageType', label: '메시지 유형', render: (r) => <Badge value={MESSAGE_TYPES.find((t) => t[0] === r.messageType)?.[1] ?? r.messageType} /> },
            { key: 'subject', label: '제목' },
            { key: 'senderName', label: '성명' },
            { key: 'sentAt', label: '발송 일시', render: (r) => <DateText value={r.sentAt} time /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span onClick={(e) => e.stopPropagation()}>
                  <button type="button" onClick={() => setTarget({ kind: 'message', row: r })}>삭제</button>
                </span>
              ),
            },
          ]}
        />
        <Pager page={msgPage} size={SIZE} total={msgs.data?.total ?? 0} onPage={setMsgPage} />
      </section>

      {detail ? (
        <Drawer title="상세" onClose={() => setDetail(null)}>
          <Pairs
            items={
              detail.messageId !== undefined
                ? [
                    ['메시지 유형', String(detail.messageType ?? '')],
                    ['제목', String(detail.subject ?? '')],
                    ['성명', String(detail.senderName ?? '')],
                    ['발송 일시', <DateText value={detail.sentAt} time />],
                    ['메시지 내용', String(detail.content ?? '')],
                  ]
                : [
                    ['알림 구분', String(detail.notificationType ?? '')],
                    ['연계 이벤트 유형', String(detail.eventType ?? '')],
                    ['제목', String(detail.title ?? '')],
                    ['요약', String(detail.summary ?? '')],
                    ['이벤트 발생 일시', <DateText value={detail.occurredAt} time />],
                  ]
            }
          />
        </Drawer>
      ) : null}

      {target ? (
        <Drawer
          title={target.kind === 'notification' ? '알림 삭제' : '메시지 삭제'}
          onClose={() => setTarget(null)}
        >
          <Form onSubmit={remove} submit="삭제" danger note="삭제하면 되돌릴 수 없습니다.">
            <Pairs
              items={[
                ['제목', String(target.kind === 'notification' ? target.row.title ?? '' : target.row.subject ?? '')],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
